// Compares the TypeScript engines with outputs generated by the Python backend (__fixtures__/reference.json), tolerance 1e-9.
import { describe, expect, it } from 'vitest'
import {
  applyAdjustments, dixonColesMatrix, expectedGoalsFromProfiles, marketProbabilities, predictMatch, walkForwardPredictions,
  type MatchRecord, type TeamProfile,
} from './football'
import { fighterProfile, predictFight } from './mma'
import { evaluateMarket, expectedValue, kellyFraction, removeVig, runBacktest, type BacktestReport } from './quant'
import reference from './__fixtures__/reference.json'
import type { FootballAdjustments, FootballPrediction, MMAPrediction } from './types'

const TOLERANCE = 1e-9

/** Recursively assert actual matches expected: numbers within tolerance (relative above 1), everything else exactly. */
function expectClose(actual: unknown, expected: unknown, path = '$'): void {
  if (typeof expected === 'number') {
    expect(typeof actual, path).toBe('number')
    expect(Math.abs((actual as number) - expected), `${path}: ${actual} vs ${expected}`).toBeLessThanOrEqual(TOLERANCE * Math.max(1, Math.abs(expected)))
  } else if (Array.isArray(expected)) {
    expect(Array.isArray(actual), path).toBe(true)
    expect((actual as unknown[]).length, `${path} length`).toBe(expected.length)
    expected.forEach((e, i) => expectClose((actual as unknown[])[i], e, `${path}[${i}]`))
  } else if (expected !== null && typeof expected === 'object') {
    for (const [k, v] of Object.entries(expected)) expectClose((actual as Record<string, unknown>)[k], v, `${path}.${k}`)
  } else {
    expect(actual, path).toEqual(expected)
  }
}

interface FootballCase {
  home: TeamProfile; away: TeamProfile; league_avg_goals: number; rho: number; lam3: number; max_goals: number
  adjustments: Partial<FootballAdjustments>; expected_goals: [number, number]; adjusted_goals: [number, number]
  prediction: Omit<FootballPrediction, 'home' | 'away' | 'elo_home' | 'elo_away'>
}
const ref = reference as unknown as {
  football: FootballCase[]
  dixon_coles: { lam: number; mu: number; rho: number; lam3: number; max_goals: number; matrix: number[][]; markets: unknown }[]
  mma: { a: Parameters<typeof fighterProfile>[0]; b: Parameters<typeof fighterProfile>[0]; rounds: 3 | 5; prediction: MMAPrediction }[]
  remove_vig: { odds: number[]; method: 'proportional' | 'power'; fair: number[] }[]
  expected_value: { prob: number; odds: number; value: number }[]
  kelly_fraction: { prob: number; odds: number; multiplier: number; cap: number; value: number }[]
  backtest: {
    matches: MatchRecord[]; warmup: number; bankroll: number; kelly_multiplier: number; min_ev: number
    rows: Record<string, unknown>[]; report: BacktestReport
  }
}

describe('reference: football', () => {
  ref.football.forEach((c, i) => {
    it(`case ${i}: expected goals, adjustments and full prediction`, () => {
      const [lam, mu] = expectedGoalsFromProfiles(c.home, c.away, c.league_avg_goals)
      expectClose([lam, mu], c.expected_goals, 'expected_goals')
      const adjustments = Object.keys(c.adjustments).length ? (c.adjustments as FootballAdjustments) : undefined
      if (adjustments) expectClose(applyAdjustments(lam, mu, adjustments), c.adjusted_goals, 'adjusted_goals')

      const p = predictMatch(c.home, c.away, {
        leagueAvgGoals: c.league_avg_goals, rho: c.rho, lam3: c.lam3, maxGoals: c.max_goals, adjustments,
      })
      expectClose(p, c.prediction)
    })
  })

  ref.dixon_coles.forEach((c, i) => {
    it(`dixon_coles case ${i}: matrix and markets (lam3 = ${c.lam3})`, () => {
      const matrix = dixonColesMatrix(c.lam, c.mu, c.rho, c.lam3, c.max_goals)
      expectClose(matrix, c.matrix, 'matrix')
      expectClose(marketProbabilities(matrix), c.markets, 'markets')
    })
  })

  it('walk-forward predictions and backtest report', () => {
    const b = ref.backtest
    const rows = walkForwardPredictions(b.matches, b.warmup)
    expectClose(rows, b.rows, 'rows')
    const report = runBacktest(
      rows.map((r) => ({
        probs: { H: r.p_home, D: r.p_draw, A: r.p_away },
        odds: { H: r.odds_home, D: r.odds_draw, A: r.odds_away },
        outcome: r.outcome,
      })),
      ['H', 'D', 'A'], b.bankroll, b.kelly_multiplier, b.min_ev,
    )
    expectClose(report, b.report, 'report')
  })
})

describe('reference: mma', () => {
  ref.mma.forEach((c, i) => {
    it(`fight ${i} (${c.rounds} rounds)`, () => {
      expectClose(predictFight(fighterProfile(c.a), fighterProfile(c.b), c.rounds), c.prediction)
    })
  })
})

describe('reference: odds maths', () => {
  it('remove_vig', () => {
    for (const c of ref.remove_vig) expectClose(removeVig(c.odds, c.method), c.fair, `${c.method} ${c.odds}`)
  })
  it('expected_value', () => {
    for (const c of ref.expected_value) expectClose(expectedValue(c.prob, c.odds), c.value, `EV ${c.prob}@${c.odds}`)
  })
  it('kelly_fraction', () => {
    for (const c of ref.kelly_fraction) {
      expectClose(kellyFraction(c.prob, c.odds, c.multiplier, c.cap), c.value, `Kelly ${c.prob}@${c.odds}`)
    }
  })
  it('evaluate_market stays consistent with its parts', () => {
    const [best] = evaluateMarket([['x', 0.55, 2.1], ['y', 0.45, 1.9]], 1000, 0.25, 0)
    expectClose(best.expected_value, 0.155)
    expectClose(best.kelly_fraction, 0.03522727272727275)
    expectClose(best.stake, 35.22727272727275)
  })
})
